def orfs_all(s, strand, minaa=50):
    res=[]; stops={'TAA','TAG','TGA'}; starts={'ATG','GTG','TTG'}
    for f in range(3):
        i=f
        while i < len(s)-2:
            if s[i:i+3] in starts:
                j=i
                while j < len(s)-2 and s[j:j+3] not in stops: j+=3
                if j-i >= minaa*3:
                    if strand=='+': start,end=i+1,j
                    else: start,end=len(s)-i,len(s)-j+1
                    res.append((start,end,(j-i)//3*1, s[i:i+3],tr(s[i:j])))
                i=j+3
            else: i+=3
    return res

